#!/bin/bash
set -eo pipefail
umask 027
python='/data1/home/sunyiq/miniconda3/envs/knet_clean/bin/python'
export PYTHONNOUSERSITE=1 PYTHONDONTWRITEBYTECODE=1
unset PYTHONPATH
"$python" -B - <<'PY'
import ast, base64, hashlib, io, json, os, pathlib, stat, subprocess, time, zipfile
root = pathlib.Path('/data1/home/sunyiq/kalmannet_tukf09_protection_diagnostic_20261001_attempt1')
payload = base64.b64decode('', validate=True)
review_raw = base64.b64decode('', validate=True)
assert hashlib.sha256(payload).hexdigest() == 'c4e41e1c131dabbb6ce6e9ab5f2e7dc3a07c77af0966cbb4f9aceaa340da25ae'
assert hashlib.sha256(review_raw).hexdigest() == '4a0ea158080fee446cb735b81e7c736085e247c5ce26438934451ed0e7dfb784'
review = json.loads(review_raw)
assert review['admission'] == 'PASS' and review['diagnostic_execution_performed'] is False
allowed = {'diagnostic_driver.py', 'diagnostic_supervisor.py', 'synthetic_worker.py',
           'budget_io.py', 'diagnostic_contract.json', 'authorization.json',
           'diagnostic_job.slurm', 'frozen_supervisor_source.py.txt', 'frozen_supervisor_tests.py.txt'}
archive = zipfile.ZipFile(io.BytesIO(payload))
names = archive.namelist()
assert len(names) == 10 and set(names) == allowed | {'payload_manifest.json'}
assert sum(x.file_size for x in archive.infolist()) < 1048576
for x in archive.infolist():
    assert x.filename in allowed | {'payload_manifest.json'} and '/' not in x.filename
    assert not x.is_dir() and stat.S_ISREG(x.external_attr >> 16)
members = {name: archive.read(name) for name in names}
manifest = json.loads(members['payload_manifest.json'])
assert len(manifest['members']) == 9
assert set(x['path'] for x in manifest['members']) == allowed
bindings = {}
for x in manifest['members']:
    b = members[x['path']]
    assert len(b) == x['bytes'] and hashlib.sha256(b).hexdigest() == x['sha256']
    bindings[x['path']] = x['sha256']
assert review['payload_member_sha256'] == bindings
auth = json.loads(members['authorization.json'])
contract = json.loads(members['diagnostic_contract.json'])
assert auth['remote_root'] == str(root) == contract['remote_root']
assert auth['maximum_scheduler_submissions'] == contract['maximum_submissions'] == 1
assert contract['requested_cpus'] == auth['requested_cpus'] == 1
assert contract['job_seconds'] == auth['scheduler_time_limit_seconds'] == 9000
assert contract['gpu_requested'] is False and contract['automatic_retry'] is False
assert auth['authorized_proposal_sha256'] == '29a2a7daef8fb5a86305b29a65c0acb199ab412adc4aded1d6c360c9fd0ea840'
for name in sorted(allowed):
    if name.endswith('.py'):
        ast.parse(members[name].decode('utf-8'), filename=name)
assert bindings['frozen_supervisor_source.py.txt'] == '4daed58001f95c474b633191454b1a664dce2596e676d4f701188c9c2b240e83'
assert bindings['frozen_supervisor_tests.py.txt'] == 'd5349df4f7b95b58203510c0f1a8214e9a9cfea6135265fade2ee12bba56a300'
for parent in (root.parent, *root.parent.parents):
    assert parent.is_dir() and not parent.is_symlink()
assert not os.path.lexists(str(root)), 'isolated root already exists; no replacement permitted'
partition = subprocess.run(['scontrol','show','partition','hcpu48y','-o'], capture_output=True, timeout=30, check=True)
assert len(partition.stdout) < 16384 and len(partition.stderr) < 16384
partition_text = partition.stdout.decode('utf-8', errors='strict')
assert 'PartitionName=hcpu48y' in partition_text and 'State=UP' in partition_text
queue = subprocess.run(['squeue','-u','sunyiq','-h','-o','%i|%P|%j|%T|%C|%R'], capture_output=True, timeout=30, check=True)
assert len(queue.stdout) < 32768 and len(queue.stderr) < 8192
space = os.statvfs(root.parent)
assert space.f_bavail * space.f_frsize >= 128 * 1048576, 'insufficient isolated storage headroom'
root.mkdir(mode=0o750)
for d in ('control','logs','tmp','cache'):
    (root / d).mkdir(mode=0o750)
def exclusive(path, data):
    fd = os.open(str(path), os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd,'wb') as stream:
        stream.write(data); stream.flush(); os.fsync(stream.fileno())
for name,b in members.items():
    exclusive(root / name, b)
exclusive(root/'control'/'independent_static_review.json', review_raw)
record = {'status':'ISOLATED_DEPLOYMENT_VERIFIED_NO_DIAGNOSTIC_EXECUTION',
          'time_unix':time.time(), 'payload_zip_sha256':'c4e41e1c131dabbb6ce6e9ab5f2e7dc3a07c77af0966cbb4f9aceaa340da25ae',
          'payload_manifest_sha256':hashlib.sha256(members['payload_manifest.json']).hexdigest(),
          'independent_review_sha256':'4a0ea158080fee446cb735b81e7c736085e247c5ce26438934451ed0e7dfb784', 'members_verified':9,
          'requested_cpus':1,'gpu_requested':False,'maximum_submissions':1,
          'scheduler_seconds':9000,'output_total_limit_bytes':67108864,
          'partition_raw':partition_text,'existing_user_jobs_raw':queue.stdout.decode(),
          'available_storage_bytes':space.f_bavail*space.f_frsize,
          'billing_note':'requested cores and scheduler-allocated/billed cores are distinct; preserve later scheduler allocation',
          'no_other_experiment_modified':True,'synthetic_execution_performed':False}
raw = (json.dumps(record,sort_keys=True,indent=2)+'\n').encode()
assert len(raw) < 65536
exclusive(root/'control'/'deployment.json',raw)
subprocess.run(['bash','-n',str(root/'diagnostic_job.slurm')],timeout=10,check=True)
assert sum(p.stat().st_size for p in root.rglob('*') if p.is_file()) < 1048576
print('DEPLOYMENT_VERIFIED '+json.dumps(record,sort_keys=True))
PY
